from fastapi import FastAPI, APIRouter

router1 = APIRouter()
router2 = APIRouter()

@router1.get('/path1')
def handler1():
    return {'msg': 'handler1'}

@router2.get('/path2')
def handler2():
    return {'msg': 'handler2'}

router1.include_router(router2)

# In 0.136.3, router1.routes contains only APIRoute instances
for route in router1.routes:
    assert hasattr(route, 'path'), f"Expected APIRoute with 'path', got {type(route)}"
    assert hasattr(route, 'endpoint'), f"Expected APIRoute with 'endpoint', got {type(route)}"
